mapper.select:
select t.* from ( select st.*, ( SELECT wm_concat(fa.FILE_NAME) from fnd_atm_attachment fa,fnd_atm_attachment_multi fam WHERE fam.table_pk_value = to_char(st.template_id) and fa.attachment_id = fam.attachment_id AND upper(fam.table_name) = 'SYS_TEMPLATE' ) file_name, ( SELECT fa.attachment_id from fnd_atm_attachment fa,fnd_atm_attachment_multi fam WHERE fam.table_pk_value = to_char(st.template_id) and fa.attachment_id = fam.attachment_id AND upper(fam.table_name) = 'SYS_TEMPLATE' and rownum=1 ) attachment_id from SYS_TEMPLATE st ) t
AND t.template_id = #{templateId}
AND t.description LIKE CONCAT(CONCAT('%',#{description}),'%')
AND t.file_name LIKE CONCAT(CONCAT('%',#{fileName}),'%')
AND t.template_code = #{templateCode}
order by t.last_update_date desc
